from collections import deque

def scan(que, ps, way):
    Li = 0
    pp = ps
    while len(que) > 0:
        if way==0:
            p = que.popleft()
        else:
            p = que.pop()
        if p < ps:
            Li += ps - p
        else:
            break
        pp = p
    return Li

