    at = 0
    bt = 0
    for s in list(S):
        if s == "c":
            print(NO)
            continue
        if at + bt < A + B:
            if s == "a":
                print(YES)
                at += 1
            elif s == "b" and bt < B:
                print(YES)
                bt += 1
            else:
                print(NO)
        else:
            print(NO)

    return


