def calc(N, T, A):
    highest = max(T)
    if highest != max(A):
        return 0
    l = T.index(highest)
    r = A.index(highest)
    if N - (l + r) <= 0:
        return 0
    elif N - (l + r) == 1:
        ans = 1
    else:
        free = N - (l + r) - 2
        ans = pow(highest, free, MOD)
    prev = 0
    for i in range(l):
        if T[i] == prev:
            ans = (ans * T[i]) % MOD
        prev = T[i]
    prev = 0
    for i in range(r):
        if A[i] == prev:
            ans = (ans * A[i]) % MOD
        prev = A[i]
    return ans


