def comb(arr, k):
    n = len(arr)
    def dfs(curr,cnt,tmp):
        ret = []
        if cnt==0:
            return [tmp]
        for i in range(curr,n-cnt+1):
            ret += dfs(i+1,cnt-1,tmp+[arr[i]])
        return ret
    return dfs(0,k,[])

