def solve():
    S = list(input())

    abc = [chr(i) for i in range(97, 123)]
    # print(abc)

    for s in S:
        if s in abc:
            abc[ord(s) - 97] = 0



    if len(S) == 26:
        # abc = [chr(i) for i in range(97, 123)]
        # print(S)
        SR = S[::-1]
        # print(SR)
        idx = (INF, INF)
        for i in range(26):
            for j in range(i+1, 26):
                if SR[i] > SR[j]:
                    # print(i, j)
                    # print(S[:-j])
                    if j < idx[1]:
                        idx = (i, j)
                    break
        # print(idx)
        i, j = idx
        if i == INF:
            print(-1)
        else:
            ans = S[:-j-1]
            ans.append(SR[i])
            printlist(ans, '')

    else:
        for t in abc:
            if t != 0:
                S.append(t)
                printlist(S, k='')
                return

