def pow_mod(x, y):
    res = 1
    while y > 0:
        if y % 2:
            res *= x
            res %= mod
        x *= x
        x %= mod
        y //= 2
    return res

def divs(x):
    res = []
    for i in range(1, x+1):
        if i * i > x:
            break
        if x % i != 0:
            continue
        res.append(i)
        if i != x // i:
            res.append(x // i)
    return res

