    if ar==[0]*len(ar):
        return 0
    m=999999999999999
    for i in range(len(ar)):
        if ar[i]<m:
            m=ar[i]
    for i in range(len(ar)):
        ar[i]-=m
    ans=m
    new=separate(ar,[0])
    for i in new:
        ans+=find(i)
    return ans








