            if i >= a and j >= b:
                dp[n][i][j] = min(dp[n - 1][i][j], dp[n - 1][i - a][j - b] + c)
            # n番目を買うことが出来ない場合(=遷移元が存在しない場合)
            else:
                dp[n][i][j] = dp[n - 1][i][j]

