def count(s, c):
	count_ = s.count(c*2)

	while c*3 in s:
		s = s.replace(c*3, c+'_'+c)

	while c*2 in s:
		s = s.replace(c*2, c+'_')

	return min(count_, s.count('_'))


def get_startswith(s, c):
	key = c

	while s.startswith(key+c):
		key += c

	return len(key)


def get_endswith(s, c):
	key = c

	while s.endswith(key+c):
		key += c

	return len(key)


