def ep(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(T, A, B):
    P = (A[0] - B[0]) * T[0]
    Q = (A[1] - B[1]) * T[1]

    if P > 0:
        P *= -1
        Q *= -1

    if P+Q == 0:
        return 'infinity'
    elif P+Q < 0:
        return 0

    S = -P // (P + Q)
    T = -P % (P + Q)
    return S * 2 + (1 if T != 0 else 0)


