    if X == prevSize + 2:
        memo2[(lv, X)] = num_pty(lv-1, prevSize) + 1
        return memo2[(lv, X)]

    memo2[(lv, X)] = num_pty(lv-1, prevSize) + 1 + num_pty(lv-1, min(X-prevSize-2, prevSize))
