def solve(N: int, M: int, p: "List[int]", x: "List[int]", y: "List[int]"):
    pars = list(range(N))

    def getpar(n: int):
        if pars[n] == n:
            return n
        pars[n] = getpar(pars[n])
        return pars[n]

    def union(a: int, b: int):
        pars[getpar(a)] = getpar(b)

    for xi, yi in zip(x, y):
        union(xi - 1, yi - 1)
