def apply(way, fr):
    logic = [False]
    for d in range(8):
        logic.append(bool(way & 1))
        way >>= 1
    if logic[fr]:
        to = fr - 1
    elif logic[fr + 1]:
        to = fr + 1
    else:
        to = fr
    return to

def isvalid(way):
    logic = []
    for d in range(7):
        logic.append(bool(way & 1))
        way >>= 1
    for d in range(6):
        if logic[d] & logic[d + 1]:
            return False
    return True

