        for j in range(i+1):
            if j != 0:
                # 表のパターンと裏のパターンの合計
                dp[i][j] = dp[i-1][j] * (1-p) + dp[i-1][j-1] * p
            else:
                # 裏のパターンのみ
                dp[i][j] = dp[i-1][j] * (1-p)
    print(sum(dp[N][(N+1)//2:]))

