    pass


MOD = 1000000007  # type: int


def solve(N: int, S: "List[str]"):
    ans = 1
    pdtype = 0
    i = 0
    while i < N:
        dtype = 2 if S[0][i] != S[1][i] else 1
        ans = {
            (0, 1): lambda: 3,
            (0, 2): lambda: 6,
            (1, 1): lambda: ans * 2,
            (1, 2): lambda: ans * 2,
            (2, 1): lambda: ans,
            (2, 2): lambda: ans * 3,
        }[pdtype, dtype]() % MOD
        i += dtype
        pdtype = dtype
    print(ans)


