def solve(n, m, a):
    b = [0]*(n+1)
    for i in range(n):
        b[i+1] = (a[i] + b[i]) % m
    c = collections.Counter(b[1:])
    total = 0
    for k, v in c.items():
        if k != 0:
            v -= 1
        if v == 0:
            continue
        total += v * (v+1)//2
    return total


