import sys


def solve(N: int, M: int, A: "List[int]"):
    from collections import defaultdict
    acc = [0] * (N+1)
    for i, a in enumerate(A, 1):
        acc[i] = (acc[i-1] + a) % M
    dp = defaultdict(int)        
    ans = 0
    for a in acc:
        ans += dp[a]
        dp[a] += 1
    return ans

