def fac1(num, div):
    """How many times can the factorial of `num` be divided by `div`?"""
    if num == 0:
        return 0
    return num // div + fac1(num // div, div)


def fac2(num, div):
    """How many times can the double factorial of `num` be divided by `div`?"""
    return fac1(num // 2, div)


