    for i in range(n):
        for j in range(n):
            if (i + j + 2) % 3 == 0:
                c0.append(grid[i][j])
            elif (i + j + 2) % 3 == 1:
                c1.append(grid[i][j])
            else:
                c2.append(grid[i][j])

    # それぞれを集計
    c0 = Counter(c0)
    c1 = Counter(c1)
    c2 = Counter(c2)

    ans = float("inf")

    # 塗り分けを全パターン試す
    for x in range(1, c + 1):
        for y in range(1, c + 1):
