    for i in range(2, int(m ** 0.5) + 1):
        while True:
            if m % i == 0:
                ls.append(i)
                m //= i
            else:
                break
    if m != 1:
        ls.append(m)
    t = 1
    ls = collections.Counter(ls)
    for k, v in ls.items():
        t *= alg_duplicate_combination_mod(n, v, mod)
        t %= mod
    print(t)


