class union_find():
    def __init__(self, id):
        self.parent = None
        self.id = id

    def root(self):
        if not self.parent:
            return self
        else:
            return self.parent.root()

    def union(self, target):
        sr = self.root().id
        tr = target.root().id
        if sr == tr:
            return
        elif sr > tr:
            self.root().parent = target.root()
        else:
            target.root().parent = self.root()


def solve():
    N, M = iip(False)

    uf = [union_find(i) for i in range(N)]

    for i in range(M):
        x, y, _ = iip(True)
        uf[x-1].union(uf[y-1])

    uf = set([i.root().id for i in uf])
