def mul(lhs, rhs):
    n = len(lhs)
    m = len(rhs)
    l = len(rhs[0])

    ret = [
        [
            sum([lhs[i][k] * rhs[k][j] for k in range(m)])
            for j in range(l)
            ]
        for i in range(n)
        ]

    return ret


