    que.append(N)
    seen = [0] * (N+1)
    seen[N] = 1
    while que:
        v = que.pop()
        for u, cost in adj[v]:
            if not seen[u]:
                seen[u] = 1
                que.append(u)
            adj_new[u].append((v, cost))

