class PriorityQueue:

    #初期化
    def __init__(self,heap):
        self.heap = heap
        heapify(self.heap)

    #値の追加
    def push(self,item):
        heappush(self.heap,item)

    #値の取り出し
    def pop(self):
        return heappop(self.heap)

    #値を追加して取り出し
    def pushpop(self,item):
        return heappushpop(self.heap,item)

    #データ構造の中身を見る
    def __call__(self):
        return self.heap

    #heapの長さ
    def __len__(self):
        return len(self.heap)

def dijkstra(s):
    #始点sから各頂点への最短距離
