    positives = []
    negatives = []
    # 絶対値の大きい方からK個取る
    for i in range(K):
        if A[i] > 0: positives.append(A[i])
        else: negatives.append(A[i])

    if len(negatives) & 1:
        # マイナスになっちゃった
