from collections import defaultdict


def to_cumsum(arr):
    arr.sort(reverse=True)
    cumsum = 0
    new = [0] * (len(arr) + 1)
    for i, e in enumerate(arr):
        cumsum += e
        new[i + 1] = cumsum
    return new


