import sys


def solve(N, K, R, S, P, T):
    d = {'r': P, 's': R, 'p': S}
    lost = set()
    ans = 0
    for i, ch in enumerate(T):
        if i < K:
            ans += d[ch]
        else:
            if T[i-K] != ch or i-K in lost:
                ans += d[ch]
            else:
                lost.add(i)
    return ans


def main(args):
    N, K = map(int, input().split())
    R, S, P = map(int, input().split())
    T = input()
    ans = solve(N, K, R, S, P, T)
    print(ans)


if __name__ == '__main__':
    main(sys.argv[1:])

def main():
    # r:ぐー,s:ちょき,p:ぱー
    # 相手のn回目の手についてn%Kの値によってグループ分け
    # 連続して同じ手を出せずに最高点を出す方法を知れば良い
    # 最後に全てを足し合わせる
    N,K = map(int, input().split())
    R,S,P = map(int, input().split())
    T = input()
    hands = [[] for i in range(K)]
    for i in range(N):
        if T[i]=='r': hands[i%K].append(0)
        elif T[i]=='s': hands[i%K].append(1)
        else: hands[i%K].append(2)
