YES = "Yes"  # type: str
NO = "No"  # type: str

def solve(N: int, s: str):
    r = 0
    for c in s:
        if c == 'R':
            r += 1
    if r * 2 > N:
        ret = YES
    else:
        ret = NO
    print(ret)
    return


