        self.connection.append(other)
        other.connection.append(self)

    def setAsRoot(self):
        self.parent = self

    def setParent(self, other: 'Island') -> None:
        self.parent = other
        self.rank = other.rank +1

class Islands(Dict[int, Island]):
    def __init__(self, num: int):
        for id in range(1, num+1):
            self[id] = Island(id)

