def solve(n,m,l):
  edges = {i+1:[] for i in range(n)}
  for i in range(m):
    a,b = l[i]
    edges[a].append(b)
    edges[b].append(a)
  def dfs(start,end,rest):
    if rest == 0:
      return start == end
    else:
      return any(dfs(nextNode,end,rest-1) for nextNode in edges[start])

  return dfs(1,n,2)



