    N, L = MI()
    tot = 0
    for i in range(1, N+1):
        tot = tot + L + i - 1
    diff = INF
    ans = 0
    for i in range(1, N+1):
        tmp = tot - L - i + 1
        if abs(tot - tmp) < diff:
            diff = abs(tot - tmp)
            ans = tmp
    print(ans)

