def solve(N: int, M: int, Q: int, L: "List[int]", R: "List[int]", p: "List[int]", q: "List[int]"):
    ends = {}
    for i in range(M):
        s, e = L[i], R[i]
        if not e in ends:
            ends[e] = {}
        if not s in ends[e]:
            ends[e][s] = 0
        ends[e][s] += 1

    counts = [[0]]
    for i in range(1, N + 1):
        tmp = [v for v in counts[i - 1]]
        tmp.append(0)
        if i in ends:
            for s, cnt in ends[i].items():
                tmp[s] += cnt
        counts.append(tmp)
    #print(counts)

    for s, e in zip(p, q):
        ret = 0
        for j in range(s, e + 1):
            ret += counts[e][j]
        print(ret)
    return

