def pakuri_poppu(c):
    c = (c & 0x5555555555555555) + (c >> 1 & 0x5555555555555555)
    c = (c & 0x3333333333333333) + (c >> 2 & 0x3333333333333333)
    c = (c + (c >> 4)) & 0x0F0F0F0F0F0F0F0F
    return c * 0x0101010101010101 >> 56 & 0x7f


def bon(x):
    p = pakuri_poppu(x)
    res = 1
    while x:
        x %= p
        p = pakuri_poppu(x)
        res += 1
    return res


