def pow_mod(n,k,m):#nのk乗したものをmod mしたものを高速に算出する関数
    if k==0:
        return 1
    if k&1:
        return (pow_mod(n,k-1,m)*n%m)%m
    else:
        return (pow_mod(n,k//2,m)**2)%m

