def count(k, bins, N):
    current = 0
    for i in range(2, N+1):
        if k * i <=N:
            if bins[k*i] == -1:raise ValueError(f'bins{i} is not filled yet')
            current += bins[k*i]
        else:
            break
    return current % 2

def check(bins):
    for b in bins[1:]:
        if b == -1:
            return False
    return True

def run():
    N = int(sysread())
    A = list(map(int, sysread().split()))
    A = [-1] + A
    bins = [-1] * (N+1)

    for i in range(N, 0, -1):
        tmp =(A[i] - count(i, bins, N)) % 2
        if bins[i] == -1 or bins[i] == tmp:
            bins[i] = tmp
        else:
            print(-1)
            return

    if check(bins):
        print(sum(bins) + 1)
        ans = []
        for i, b in enumerate(bins):
            if b == 1:
                ans.append(str(i))
        print(' '.join(ans))

    else:
        print(-1)

if __name__ == "__main__":
    run()

