import sys


def solve(N: int, S: str):
    w = [0] * N
    e = [0] * N
    wt = 0
    et = 0
    a = [0] * N
    for i in range(N):
        s = S[i]
        w[i] = wt
        if s == "W":
            wt += 1
        if s == "E":
            et += 1
        e[i] = et
    for i in range(N):
        a[i] = w[i] + et - e[i]
    print(min(a))




    return


