    if lst[0] < x:
        return 0
    if x <= lst[-1]:
        return len(lst)

    a = 0
    b = len(lst) - 1

    while abs(b - a) > 1:
        c = (a + b) // 2

        if lst[c] < x:
            b = c
        else:
            a = c

    return b

