def slv(N, A, B, H):
    c = A-B
    def f(n):
        m = n
        for h in H:
            h -= n * B
            if h > 0:
                m -= -(-h // c)
        return 1 if m >= 0 else 0

    return Bisect(f).bisect_left(1, 0, 10**9)



