def ep(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, K, A):
    c = Counter()
    for a in A:
        for i in range(64):
            if a & (1 << i) != 0:
                c[i] += 1

    x = 0
    for i in range(63, -1, -1):
        m = 1 << i
        if x + m > K:
            continue
