def DFS(ni,ki,sm):
    if ni == 0:
        if ki == 0:
            return sm+g0[0]
        else:
            return sm+ss[0]
    else:
        if ki//t2[ni] == 0:
            return DFS(ni-1,ki,sm+g0[ni])
        elif ki//t2[ni] > 1:
            return sm+ss[ni]
        else:
            return max(sm+g0[ni]+ss[ni-1],DFS(ni-1,ki-t2[ni],sm+g1[ni]))

