    bit_K = [int(bin_K[-(i+1)]) for i in range(max_len)]
    f_val = [0 for _ in range(len_K)]
    for free_len in range(len_K):
        if bit_K[free_len] == 0:
            continue
        digit_x = [0 for _ in range(max_len)]
        for j, (ba, bk) in enumerate(zip(bit_A_sum, bit_K)):
