            X[i] += 1

Y = [max(x, N-x) for x in X]

@lru_cache(None)
def cal(index, total):
    total += sum([y * 2 ** i for i, y in enumerate(Y[:index+1])])
    return total

@lru_cache(None)
def dfs(index, sum, y):
    if index == limit:
        return sum
    i = limit - 1 - index
    if y + 2 ** (i + 1) <= K:
        return cal(i, sum)
    ret = dfs(index+1, sum + X[i] * 2 ** i, y)
    if y + 2 ** i <= K:
        ret = max(ret, dfs(index+1, sum+(N-X[i])*2**i, y+2**i))
    return ret

