def binary_search(x, c_nums):
    l = 0
    r = c
    while l + 1 != r and c != 0:
        m = (l + r) // 2
        if c_nums[m] == x:
            return 1
        elif c_nums[m] < x:
            l = m
        elif c_nums[m] > x:
            r = m
        m = (l + r) // 2
    if x == c_nums[l] or x == c_nums[r]:
        return 1
    else:
        return 0


