def mult(a,b):
    #a以上の最小のbの倍数
    d = (a-1)//b
    return b*(d+1)

def mov(CSF,st):
    N = len(CSF)
    time = 0
    for i in range(st,N):
        c,s,f = CSF[i][0],CSF[i][1],CSF[i][2]
        time = max(time,s)
        time = mult(time,f) + c
    return time

