def search(a, s):
    min_i = 0
    max_i = len(a)-1
    i = int(len(a)/2)

    if a[min_i] < s and s < a[max_i]:
        while True:
            if a[i] <= s and s < a[i+1]:
                break
            elif s < a[i]:
                max_i = i
                i = min_i + int((max_i - min_i)/2)
            else:
                min_i = i
                i = min_i + int((max_i - min_i)/2)

        return i
    elif s <= a[min_i]:
        return min_i
    else:
        return max_i

