grid = [[0]*W for _ in range(H)]
for i in range(H):
    grid[i] = list(map(int, input().split()))

done = [[0]*W for _ in range(H)]

def nex(y,x):
    for new_y,new_x in [[y,x+1],[y+1,x],[y-1,x],[y,x-1]]:
        if 0<=new_y<H and 0<=new_x<W and not done[new_y][new_x]:
            return [new_y,new_x]
    return False

