    previous_y, previous_x = y,x
    have_odd = True
else:
    have_odd = False

while True:
    if not nex(y,x):
        break
    y,x  = nex(y,x)
    done[y][x] = 1

    # 奇数をもった状態での移動
    if have_odd:
        if grid[y][x] % 2 == 1:
            ans_ls.append([y+1,x+1,previous_y+1,previous_x+1])
            have_odd = False
