def nxt(y, x, h, w):
    if y % 2 == 0:
        if x < w - 1:
            yn, xn = y, x + 1
        else:
            yn, xn = y + 1, w - 1
    else:
        if x > 0:
            yn, xn = y, x - 1
        else:
            yn, xn = y + 1, 0
    return yn, xn


