try:
    from typing import List
except ImportError:
    pass


def solve(N: int, K: int, A: "List[int]"):
    m = min(A)
    m1 = A.index(m)
    ans = -(-m1 // (K - 1))
    c = ans * (K - 1) + 1
    while c < N:
        while A[c] == m:
            c += 1
        c += K - 1
        ans += 1
    print(ans)


