def is_ok(x, f):
    for d in a:
        x = x - x % d
    return f(x)


def binary_search(f, ok, ng):
    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if is_ok(mid, f):
            ok = mid
        else:
            ng = mid
    return ok


