from collections import defaultdict


class DisjointSet:

    def __init__(self, N):
        self.parents = [i for i in range(N)]
        self.count = N

    def find(self, x):
        path = []
        while self.parents[x] != x:
            x = self.parents[x]
            path.append(x)
        for p in path:
            self.parents[p] = x
        return x

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if self.find(root_x) != self.find(root_y):
            self.parents[root_x] = root_y
            self.count -= 1


