      return self.root[x]

  def unite(self, x, y):
    xr = self.find(x)
    yr = self.find(y)
    if xr == yr:
      return
    elif self.rank[xr] < self.rank[yr]:
      self.root[yr] += self.root[xr]
      self.root[xr] = yr
    else:
      self.root[xr] += self.root[yr]
      self.root[yr] = xr
      if self.rank[xr] == self.rank[yr]:
        self.rank[xr] += 1

  def same(self, x, y):
    return self.find(x) == self.find(y)

  def count(self, x):
    return -self.root[self.find(x)]

