def bfs(n):
    graph = [[] for i in range(N)]

    for i in range(n):
        v, u = map(int, input().split())
        graph[v-1].append(u-1)
        graph[u-1].append(v-1)

    root = [i for i in range(N)]
    visited = [False] * N

    for i in range(N):
        if not visited[i]:
            q = graph[i]
            visited[i] = True

            while q:
                v = q.pop()
                root[v] = i
                visited[v] = True
                for u in graph[v]:
                    if not visited[u]:
                        visited[u] = True
                        q.append(u)
                        root[u] = i

    return root

