    a, b = s.root(s.L[x])
    s.L[x] = a
    return a, b
  def merge(s, a, b):
    ra, sa = s.root(a)
    rb, sb = s.root(b)
    if ra != rb:
      if sa < sb:
        s.L[ra] = rb
        s.L[rb] -= sa
      else:
        s.L[rb] = ra
        s.L[ra] -= sb
      return True
    return False


