class node():
    def __init__(self, data, child=None):
        self.child = child
        self.data = data

class head():
    def __init__(self, data):
        self.child = None
        self.length = 0
        for i in data:
            self.add(i)

    def add(self, i):
        self.child = node(i, child=self.child)
        self.length += 1

    def remove(self):
        idx = self.length
        root = self
        child = self.child
        while child is not None:
            if child.data == idx:
                root.child = child.child
                self.length -= 1
                return child.data
            idx -= 1
            root = child
            child = root.child

        return False

