import math
import collections
def trial_division_prime(n, prime_list,prime_count):
    tmp=collections.Counter()
    for i in prime_list:
        if i * i > n:
            break
        while n % i == 0:
            n /= i
            tmp[i] += 1
    if n > 1:
        tmp[int(n)] += 1
    for num,rui in tmp.items():
        if prime_count[num]<rui:
            prime_count[num]=rui
        else:
            continue
    return prime_count
