def cc(s):
	if s <= 10**9:
		r = [0,0,s,0,0,1]
		return r

	ok=10**9
	ng=1
	while ok-ng > 1:
		mid = (ok+ng)//2
		if mid * mid >= s:
			ok = mid
		else:
			ng = mid
	if ok*ok == s:
		r = [0,0,ok,0,0,ok]
		return r

	mx = ok
	ok = mx
	ng = 1
	while ok - ng > 1:
		mid = (ok+ng)//2
		if mx * mid >= s:
			ok = mid
		else:
			ng = mid

	if mx * ok == s:
		return [0,0,mx, 0, 0, ok]

	else:
		diff = (mx * ok) - s
		#dd=s-(mx*ok)
		#pa(dd)
		#pa(mx*ok-diff)
		#pa(s)
		return [0,0,mx,1,diff, ok]






