import sys


def solve(N: int):
    from itertools import takewhile, count
    dp = list(range(N+1))
    for n in (6, 9):
        for m in takewhile(lambda x: x<=N, (n**e for e in count(1))):
            for i in range(m, N+1):
                dp[i] = min(dp[i], dp[i-m]+1)
    return dp[N]


