def binom_64bit(n):
    c = [1 for i in range(n+1)]
    for k in range(1, n):
        c[k] = c[k-1] * (n-k+1) // k
    return c


def solve(N, P, A):
    B = Counter([a % 2 for a in A])
    C0 = binom_64bit(B[0])
    C1 = binom_64bit(B[1])
    ans = 0
    if P == 1:
        for i in range(0, B[0]+1):
