def solve(N: int, M: int, P: "List[int]", S: "List[str]"):
    ac = [0] * N
    wa = [0] * N
    for p, s in zip(P, S):
        if s == "AC":
            ac[p - 1] = 1
        else:  # WA
            if ac[p - 1] == 0:
                wa[p - 1] += 1
    for i in range(N):
        if ac[i] == 0:
            wa[i] = 0

    return sum(ac), sum(wa)


