def prime_factors(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            yield i
    if n > 1:
        yield n

def all_divisors(n):
    factors,counts = map(tuple,zip(*Counter(prime_factors(n)).items()))

    for p in product(*(range(c+1) for c in counts)):
        yield nproduct(v**k for v,k in zip(factors,p))

def num_divisors(n):
