from collections import deque
def deque_divisor(n):
    d = deque()
    for i in range(int(n**(1/2)),0,-1):
        if i**2 == n:
            d.append(i)
            continue
        if n % i == 0:
            d.appendleft(i)
            d.append(n//i)
    return d

