def main():
    n = int(input())
    S = sorted([list(input()) for i in range(n)], key = lambda x : len(x))
    common = [[False for i in range(len(X))] for X in S]

    ref = S[0]
    ans = list()
    for i in range(len(ref)):

        is_common = True
        for j in range(1, len(S)):

            find = False
            for k in range(len(S[j])):
                if S[j][k] == ref[i] and common[j][k] == False:
                    common[j][k] = True
                    find = True
                    break

            is_common &= find

        if is_common:
            ans.append(ref[i])

    print("".join(sorted(ans)))

if __name__ == "__main__":
    main()

def common_str(n,listt):
    ans_list = []
    flag = True

    while flag:
        com = set(listt[0])
        for i in range(1,n):
            com &= set(listt[i])
        a = list(com)
        if len(a) != 0:
            for i in range(len(com)):
                ans_list.append(list(com)[i])
                for j in range(n):
                    listt[j].remove(list(com)[i])
        else:
            flag = False

    return ans_list

