def traverse(i, j):
    path = 0
    if i < n-1 and j < m-1:
        if dp[i][j] != -1:
            return dp[i][j]
    if i == n - 1 and j == m - 1:
        return 1
    elif i == n - 1:
        if grid[i][j + 1] != "#":
            path += traverse(i, j + 1)
    elif j == m - 1:
        if grid[i + 1][j] != "#":
            path += traverse(i + 1, j)
    else:
        if grid[i + 1][j] != "#":
            path += traverse(i + 1, j)
        if grid[i][j + 1] != "#":
            path += traverse(i, j + 1)
    dp[i][j] = path
    return path % (10 ** 9 + 7)


