def warshall_floyd(d,ans):
    #d[i][j]: iからjへの最短距離
    flag=True
    for i in range(n):
        for j in range(n):
            x=d[i][j]
            y=float('inf')
            for k in range(n):
                if k!=i and k!=j:
                    y = min(d[i][k] + d[k][j],y)
            if x==y:
                ans-=y
            elif x<y:
                continue
            else:
                flag=False
                break

    return flag,ans

