import numpy as np


def solve(N, M, X, C, A):
    answer = float("inf")
    for ptn in range(1, 1 << len(C)):
        buy = [ptn & 1 << i == 1 << i for i in range(len(C))]
        if (A[buy].sum(axis=0).min() >= X) and (
            C[buy].sum() < answer
        ):
            answer = C[buy].sum()

    if answer == float("inf"):
        return -1

    return answer


