    elif x == w-1:
        # grid の一番右列。右上と右下のパターンは考えなくてOK
        if grid[y][x-1] == '#' or grid[y-1][x] == '#' or grid[y+1][x] == '#':
            return True
        else:
            return False
    else:
        # 端っこの列じゃない場合
        if grid[y+1][x] == '#' or grid[y-1][x] == '#' or grid[y][x+1] == '#' or grid[y][x-1] == '#':
            return True
        else:
