            ai, bi = a // g, b // g
            c1 = (ai, bi) if ai > 0 else (-ai, -bi)
            c2 = (bi, -ai) if bi > 0 else (-bi, ai)
        elif a == 0:
            c1 = (0, 1)
            c2 = (1, 0)
        elif b == 0:
            c1 = (1, 0)
            c2 = (0, 1)

        if c1 in d:
            d[c1][0] += 1
        elif c2 in d:
            d[c2][1] += 1
        else:
            d[c1] = [1, 0]

    mod = 1000000007
    ans = 1
    for k in d:
        n = modpow(2, d[k][0], mod)
        m = modpow(2, d[k][1], mod)
        ans = ans * (n + m - 1) % mod

    ans = (ans + z - 1) % mod

    print(ans)


