#!/usr/bin/env python3
import sys
sys.setrecursionlimit(10**8)
INF = float("inf")


def yes():
    print("Yes")  # type: str


def no():
    print("No")  # type: str


def solve(N: int, S: "List[str]"):

    def seq_positive(ls):
        state = 0
        for l, st in ls:
            if state+l < 0:
                return False
            state += st
        return True

    # 部分括弧列の特徴量を計算する。
    # 経過中の最小値と、最終到達値
    left_seq = []
    right_seq = []
    total = 0
    for s in S:
        state = 0
        lower = 0
        for c in s:
            if c == "(":
                state += 1
            else:
                state -= 1
            lower = min(lower, state)
        if state > 0:
            left_seq.append((lower, state))
        else:
            right_seq.append((lower-state, -state))
        total += state

    left_seq.sort(reverse=True)
    right_seq.sort(reverse=True)
    # print(left_seq)
    # print(right_seq)

    if seq_positive(left_seq) and seq_positive(right_seq) and total == 0:
        yes()
    else:
        no()

    return


def main():

    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    S = [next(tokens) for _ in range(N)]  # type: "List[str]"
    solve(N, S)


if __name__ == '__main__':
    main()

import cython

def main():
    import sys
    readline = sys.stdin.readline

    N: cython.longlong
    N = int(readline())
    S = [readline().strip() for i in range(N)]

    D = []
    L, R = [], []
    for s in S:
        l: cython.longlong = 0
        r: cython.longlong = 0
        for c in s:
            if c == ')':
                if l > 0: l -= 1
                else: r += 1
            else: l += 1
        if l == 0 and r == 0:pass
        elif l == 0: R.append(r)
        elif r == 0: L.append(l)
        else: D.append((l, r))

    L: cython.longlong
    R: cython.longlong
    L = sum(L)
    R = sum(R)

    inc = []
    dec = []
    for l, r in D:
        if l > r:
            inc.append((l, r))
        else:
            dec.append((l, r))

    inc.sort(key=lambda x:x[1])
    dec.sort(key=lambda x:-x[1])

    D = inc + dec

    l: cython.longlong
    r: cython.longlong
    for _, (l,r) in enumerate(D):
        L -= r
        if L < 0:
            print('No')
            exit(0)
        L += l

    if L == R:
        print('Yes')
