def solve(n,m,queries):
  redInBox   = [False] * (n+1)
  amountOfBalls = [1] * (n+1)
  redInBox[1] = True

  for query in queries:
    x,y = query
    if redInBox[x]:
      redInBox[y] = True
      amountOfBalls[x] -= 1
      amountOfBalls[y] += 1
      if amountOfBalls[x] == 0:
        redInBox[x] = False
    else:
      amountOfBalls[x] -= 1
      amountOfBalls[y] += 1

  return sum(redInBox)



