import sys


def sieve(N):
    is_prime = [True] * (N + 1)
    prime_list = []

    is_prime[0] = is_prime[1] = False

    prime_list.append(2)
    for i in range(3, N + 1, 2):
        if is_prime[i]:
            prime_list.append(i)
        for j in range(i * i, N, i):
            is_prime[j] = False

    return prime_list

