    # [0, 0, ..., 0]の数列に対し、「どれかを-2」「どれかを+1」をk回ずつやってDを作れるか？
    cnt_m2 = 0
    cnt_p1 = 0
    # 必要最低限な個数を計算
    for d in D:
        if d < 0:
            if d % 2 == 0:
                cnt_m2 += abs(d) // 2
            else:
                cnt_m2 += (abs(d) + 1) // 2
                cnt_p1 += 1
        elif d > 0:
            cnt_p1 += d
    # 基本的に「-2の回数」==「+1の回数」にできればYes。
