    # 相殺可能な操作を足して「-2の回数」==「+1の回数」にできればYes。
    # つまり cnt_m2 >= cnt_p1 ならYes。
    if cnt_m2 >= cnt_p1:
        print('Yes')
    else:
        print('No')


